import csv
rows=[dict({'Record Type':'CORE'},**r) for r in d['core_facets']]+[dict({'Record Type':'SEGMENT'},**r) for r in d['facets']];keys=list(dict.fromkeys(k for r in rows for k in r))
with (p.parent/'Wendys_Company_and_Segment_Facets.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=keys);w.writeheader();w.writerows({k:json.dumps(v,ensure_ascii=False) if isinstance(v,(dict,list)) else v for k,v in r.items()} for r in rows)
